package com.example.disputeportal.entity;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * This seeks to define users of the system, which are either ordinary customers
 * or admins.
 */
@Entity
@Table(name = "customers")
public class Customer {

    /**
     * Primary key, generated by the database (an identity column).
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Login name. Unique.
     */
    @Column(nullable = false, unique = true, length = 50)
    private String username;

    /**
     * BCrypt hash of the password. The plain password is never stored or
     * logged.
     */
    @Column(name = "password_hash", nullable = false, length = 100)
    private String passwordHash;

    /**
     * Display name shown in the admin queue.
     */
    @Column(name = "full_name", nullable = false, length = 100)
    private String fullName;

    /**
     * CUSTOMER or ADMIN. Stored as text so the database stays readable.
     */
    @Enumerated(EnumType.STRING)
    @Column(nullable = false, length = 20)
    private Role role;

    protected Customer() {
        // required by JPA
    }

    /**
     * Creates an ordinary customer.
     */
    public Customer(String username, String passwordHash, String fullName) {
        this(username, passwordHash, fullName, Role.CUSTOMER);
    }

    /**
     * Creates an account with an explicit role (used for admins).
     */
    public Customer(String username, String passwordHash, String fullName, Role role) {
        this.username = username;
        this.passwordHash = passwordHash;
        this.fullName = fullName;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public String getUsername() {
        return username;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public String getFullName() {
        return fullName;
    }

    public Role getRole() {
        return role;
    }
}
